import{_ as e,o as n,c as i,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Testing Meeting 2018-10-17","description":"","frontmatter":{"title":"Ceph Testing Meeting 2018-10-17","date":"2018-10-17T00:00:00.000Z","updated":"2018-10-19T00:00:00.000Z","tags":["Ceph","分布式存储","开发讨论","问题解决","测试"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Ceph_Testing_Meeting_2018-10-17.md","filePath":"posts/2018/Ceph_Testing_Meeting_2018-10-17.md","lastUpdated":1780460162000}'),l={name:"posts/2018/Ceph_Testing_Meeting_2018-10-17.md"};function o(p,t,r,a,g,_){return n(),i("div",null,[...t[0]||(t[0]=[s('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2018年10月17日</p><p><strong>参会人员</strong>： [请填写参会人员名单]</p><p><strong>会议主题</strong>： Ceph 存储项目开发讨论与问题解决</p><p><strong>会议内容</strong>：</p><p><strong>1. 维护活动</strong>：</p><ul><li>讨论了是否进行维护活动，决定可能今天不进行在线维护。</li><li>Nathan 在线，讨论了相关的 PRs，并提到有一个 PR 已准备好合并。</li></ul><p><strong>2. 内部讨论</strong>：</p><ul><li>有关安装界面的设置讨论正在进行中，计划下周开始着手进行。</li><li>目前正在审查 outstanding PRs，特别是关于自定义仓库的 PR。</li></ul><p><strong>3. 技术问题与解决方案</strong>：</p><ul><li>讨论了关于大系列补丁的问题，指出这些补丁可能需要一些额外的“punch”来确保夏季级别的修复。</li><li>讨论了测试环境中的问题，特别是关于测试脚本 <code>talks</code> 的使用。</li><li>使用了虚拟环境来手动运行测试，因为 <code>talks</code> 需要从系统中安装旧的依赖项，无法升级到最新版本。</li><li>发现了系统中的某些问题，需要从上游获取帮助来解决。</li></ul><p><strong>4. Jenkins 任务</strong>：</p><ul><li>讨论了 Jenkins 任务的使用，特别是针对 SAP Jenkins 任务的审查。</li><li>发现了一个使用系统 Python 打包的设置，而不是使用自定义打包，这让人感到意外。</li></ul><p><strong>5. 行动计划</strong>：</p><ul><li>Nathan 将审查自定义仓库的 PR。</li><li>计划下周开始设置安装界面。</li><li>解决测试环境中的问题，并从上游获取帮助。</li><li>审查 Jenkins 任务，并确保其正确性。</li></ul><p><strong>6. 其他事项</strong>：</p><ul><li>如果在开发过程中遇到问题，可以通过邮件或 CC 讨论者来寻求帮助。</li><li>鼓励大家更多地参与讨论。</li></ul><p><strong>会议总结</strong>：</p><p>本次会议讨论了 Ceph 存储项目开发中的多个问题，包括维护活动、内部讨论、技术问题与解决方案、Jenkins 任务的使用等。会议确定了行动计划，包括审查 PRs、设置安装界面、解决测试环境问题等。会议强调了测试环境和 Jenkins 任务的正确性，并鼓励团队成员积极参与讨论和解决问题。</p>',19)])])}const c=e(l,[["render",o]]);export{u as __pageData,c as default};
